create index if not exists idx_vocabulary_level on public.vocabulary(level); create index if not exists idx_kanji_level on public.kanji(level); create index if not exists idx_grammar_points_level on public.grammar_points(level); create index if not exists idx_reading_passages_level_published on public.reading_passages(level,is_published); create index if not exists idx_listening_items_level_published on public.listening_items(level,is_published); create index if not exists idx_questions_level_skill_published on public.questions(level,skill,is_published);
